components.c_create:
lv_obj_t* %name% = lv_btn_create(%parent%);
    lv_obj_set_size(%name%, %width%, %height%);
    lv_obj_set_pos(%name%, %x%, %y%);
    lv_obj_add_event_cb(%name%, %event_callback%, LV_EVENT_CLICKED, NULL);
    lv_obj_t* %name%_label = lv_label_create(%name%);
    lv_label_set_text(%name%_label, "%text%");
    lv_obj_center(%name%_label);

lv_obj_t* %name% = lv_slider_create(%parent%);
    lv_obj_set_size(%name%, %width%, %height%);
    lv_obj_set_pos(%name%, %x%, %y%);
    lv_slider_set_range(%name%, %min%, %max%);
    lv_slider_set_value(%name%, %value%, LV_ANIM_OFF);
    lv_obj_add_event_cb(%name%, %event_callback%, LV_EVENT_VALUE_CHANGED, NULL);

lv_obj_t* %name% = lv_switch_create(%parent%);
    lv_obj_set_size(%name%, %width%, %height%);
    lv_obj_set_pos(%name%, %x%, %y%);
    if (%state%) lv_obj_add_state(%name%, LV_STATE_CHECKED);
    lv_obj_add_event_cb(%name%, %event_callback%, LV_EVENT_VALUE_CHANGED, NULL);

lv_obj_t* %name% = lv_meter_create(%parent%);
    lv_obj_set_size(%name%, %width%, %height%);
    lv_obj_set_pos(%name%, %x%, %y%);
    lv_meter_scale_t* %name%_scale = lv_meter_add_scale(%name%);
    lv_meter_set_scale_ticks(%name%, %name%_scale, 41, 2, 10, lv_palette_main(LV_PALETTE_GREY));
    lv_meter_set_scale_range(%name%, %name%_scale, %min%, %max%, 270, 135);
    lv_meter_indicator_t* %name%_indic = lv_meter_add_needle_line(%name%, %name%_scale, 4, lv_palette_main(LV_PALETTE_RED));
    lv_meter_set_indicator_value(%name%, %name%_indic, %value%);

lv_obj_t* %name% = lv_chart_create(%parent%);
    lv_obj_set_size(%name%, %width%, %height%);
    lv_obj_set_pos(%name%, %x%, %y%);
    lv_chart_set_type(%name%, LV_CHART_TYPE_%type%);
    lv_chart_set_point_count(%name%, %point_count%);
    lv_chart_set_range(%name%, LV_CHART_AXIS_PRIMARY_Y, %min_y%, %max_y%);
    lv_chart_series_t* %name%_ser = lv_chart_add_series(%name%, lv_palette_main(LV_PALETTE_BLUE), LV_CHART_AXIS_PRIMARY_Y);

lv_obj_t* %name% = lv_spinbox_create(%parent%);
    lv_obj_set_size(%name%, %width%, %height%);
    lv_obj_set_pos(%name%, %x%, %y%);
    lv_spinbox_set_range(%name%, %min%, %max%);
    lv_spinbox_set_digit_format(%name%, 4, 0);
    lv_spinbox_set_step(%name%, %step%);
    lv_spinbox_set_value(%name%, %value%);

lv_obj_t* %name% = lv_keyboard_create(%parent%);
    lv_obj_set_size(%name%, %width%, %height%);
    lv_obj_set_pos(%name%, %x%, %y%);
    lv_keyboard_set_mode(%name%, LV_KEYBOARD_MODE_%mode%);
